window.LD=window.LD||{};window.LD["party/p5"]={"id":"p5","name":"The Scarlet Gallopers","poss":"The Scarlet Gallopers'","members":["h4","h15","h5"],"leader":"h4","morale":93,"disposition":"wary","motto":"Check for traps. Check again.","banner":{"c1":"#c8323c","c2":"#e8c83a","emblem":"horseshoe"},"loc":"ashveil_crypts","loc_name":"The Ashveil Crypts","goal":{"text":"to finish the season as one of the top three parties","kind":"top","done":90,"progress":"currently 3rd","missed":false,"crew":"The Scarlet Gallopers","party":"p5"},"vows":[{"text":"that no one leaves this party","day":31,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The Scarlet Gallopers","party":"p5"}],"doing":"last seen delving into The Ashveil Crypts","progress":null,"today":["XP: Pickles +800 (level 19!), Rook +960, Morwen +960.","Coin between them: +61 silver.","Came away with a healing potion.","Ate 6 rations.","Used up 5 torches."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"rangers_promise","title":"The Ranger's Promise","tone":"heroic","meter":"6/8","bpm":98,"diff":3,"day":88,"night":"n220","n":4,"by":null,"lead":{"id":"h15","name":"Rook","skill":0.937,"inst":"drum"}},"renown":176,"season":{"wins":8,"bosses":0,"floors":4,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30},"career":{"wins":21,"bosses":2,"floors":12,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":1},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"ox_wagon","name":"The Creak","label":"ox wagon","seats":5,"haul":70,"comfort":0,"since":84,"desc":"Slow as a wedding, carries a house.","moves":true,"puller":{"kind":"ox","name":"Big Tom","label":"ox","colour":"cream","owner":null},"paid":[["Pickles",56],["Rook",7],["Morwen",1]]},"pace_gap":0,"rels":[{"party":"p8","score":100},{"party":"p6","score":31},{"party":"p1","score":23},{"party":"p3","score":6},{"party":"p4","score":4}],"events":[{"id":"e30","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Pickles and Rook shake on it at The Sagging Beam: they are now The Scarlet Gallopers. (Friendly, by the look of them.)","heroes":["h4","h15"],"parties":["p5"],"loc":"thornwall","wx":"storm"},{"id":"e222","day":6,"season":1,"sday":6,"kind":"boss","imp":5,"text":"Old Grizzlemaw, a Wolf and a Dire Wolf have held the bottom of the Wolf Den long enough: the Scarlet Gallopers kill them. Pickles' Feint knocked half the fight out of the dire wolf. One Fire Arrow from Morwen, and the wolf stopped being a problem. Inspire, from Pickles, at exactly the right moment. The others will say it was close. Morwen made sure it wasn't. Loot: 8 pelts, 6 fangs & claws, Grizzlemaw's honeycomb.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"wolf_den","fight":"f26","foes":["cave_bear","wolf","dire_wolf"],"where":"at the bottom of The Wolf Den","won":true,"close":false,"shape":"foe","reworded":-25},{"id":"e225","day":6,"season":1,"sday":6,"kind":"gear","imp":4,"text":"Pickles carries a heavy coat of grey bear fur from the old bear's winter chamber up out of the Wolf Den wrapped in a cloak. It hums. Someone in town will have to say why.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"wolf_den"},{"id":"e257","day":6,"season":1,"sday":6,"kind":"big_move","imp":4,"text":"Old Grizzlemaw, a Wolf and a Dire Wolf have held the bottom of the Wolf Den long enough: the Scarlet Gallopers kill them. On the table: The Scarlet Gallopers +90 party renown (4th to 1st among the crews).","heroes":["h4","h15","h5"],"parties":["p5"],"party_moves":[{"party":"p5","gain":90,"from":4,"to":1}],"cause":"e222","fight":"f26"},{"id":"e766","day":20,"season":1,"sday":20,"kind":"delve","imp":1,"text":"The Scarlet Gallopers descend into the Collapsed Mine, partly explored (57%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","wx":"heat"},{"id":"e767","day":20,"season":1,"sday":20,"kind":"delve_day","imp":1,"text":"Down in the Collapsed Mine, The Scarlet Gallopers map nine rooms of the first floor, with a look round every corner (the powder shed, the adit mouth, the pithead and 6 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"cautious","stats":{"rooms":9,"empty":9,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"heat"},{"id":"e793","day":21,"season":1,"sday":21,"kind":"delve_day","imp":1,"text":"The first floor of the Collapsed Mine, taken without hurrying: The Scarlet Gallopers get through nine rooms (the ore bins, the foreman's office, a ladderway bolted to the rock and 6 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"steady","stats":{"rooms":9,"empty":9,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"heat"},{"id":"e808","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Rook hears the bats change their call at the Collapsed Mine and pulls the crew back. Something big goes past.","heroes":["h15"],"parties":["p5"],"loc":"collapsed_mine","skill":"bird_caller","wx":"heat"},{"id":"e851","day":22,"season":1,"sday":22,"kind":"wild_room","imp":3,"text":"Pickles sat down at the kobolds' lunch table in the Collapsed Mine and ate a plate of Rat-on-a-Stick. The cook is said to be 'overcome.'","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","room":"wild_kobold_lunch"},{"id":"e852","day":22,"season":1,"sday":22,"kind":"delve_day","imp":1,"text":"By lamplight on the bottom floor of the Collapsed Mine, The Scarlet Gallopers clear the way through five rooms, one door at a time: the sick bay, the overseer's room, a crosscut and 2 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"steady","stats":{"rooms":5,"empty":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":0,"wild":["wild_kobold_lunch"]}},{"id":"e879","day":23,"season":1,"sday":23,"kind":"trap","imp":2,"text":"Pickles springs a gas pocket in the powder magazine on the bottom floor of the Collapsed Mine (bruised ribs) (Morwen hurt too).","heroes":["h4","h5"],"parties":["p5"],"loc":"collapsed_mine"},{"id":"e880","day":23,"season":1,"sday":23,"kind":"delve_day","imp":1,"text":"The Scarlet Gallopers spend the day on the bottom floor of the Collapsed Mine, steadily, and cover five rooms: the miners' dry stair, the powder magazine, the pay window and 2 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"steady","stats":{"rooms":5,"empty":1,"size":3,"floor":2,"traps":1,"sprung":1,"trap_inj":2,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e925","day":24,"season":1,"sday":24,"kind":"fight","imp":2,"text":"In the spiders' harp gallery on the bottom floor of the Collapsed Mine, the Scarlet Gallopers defeat 4 Giant Spiders. One Fire Arrow from Morwen and two giant spiders were on the ground. Morwen and Aimed Shot between them took three out of the fight. Loot: 7 chitin, 4 spider legs.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","fight":"f63","foes":["giant_spider","giant_spider","giant_spider"],"where":"in the spiders' harp gallery on the bottom floor of the Collapsed Mine","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e926","day":24,"season":1,"sday":24,"kind":"gear","imp":1,"text":"In the kobold shrine on the bottom floor of the Collapsed Mine, Rook finds a pair of Quick Grip Gloves and puts them on. Quicker (+0.8 speed).","heroes":["h15"],"parties":["p5"],"loc":"collapsed_mine"},{"id":"e927","day":24,"season":1,"sday":24,"kind":"delve_day","imp":1,"text":"The map of the Collapsed Mine grows by three rooms of the bottom floor, walked at a steady pace by The Scarlet Gallopers: the new tunnels, the kobold shrine, the glowworm grotto.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"steady","stats":{"rooms":3,"empty":0,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great"],"fears":0,"wild":[]}},{"id":"e949","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"Torch by torch through the bottom floor of the Collapsed Mine, The Scarlet Gallopers make it through two rooms, at a cautious pace: The Widow's Shaft, the sump.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"cautious","stats":{"rooms":2,"empty":0,"size":3,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e1000","day":26,"season":1,"sday":26,"kind":"fight","imp":2,"text":"The Scarlet Gallopers see off 4 Giant Spiders in the nest mouth on the bottom floor of the Collapsed Mine without much fuss. The last giant spider bolts. Rook's Caltrops took the strength out of the giant spider. Loot: 6 chitin, a giant spider leg.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","fight":"f67","foes":["giant_spider","giant_spider","giant_spider"],"where":"in the nest mouth on the bottom floor of the Collapsed Mine","won":true,"close":false,"shape":"plain","reworded":-18},{"id":"e1001","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"Another day under the Collapsed Mine: The Scarlet Gallopers walk two rooms of the bottom floor, slowly, chalking every door (the nest mouth, the flooded gallery).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"cautious","stats":{"rooms":2,"empty":0,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":1,"wild":[]}},{"id":"e1011","day":26,"season":1,"sday":26,"kind":"argument","imp":3,"text":"Morwen and Pickles spend supper disagreeing about who lost the map, politely at first. (A street palmist in Thornwall said this would happen. Morwen is going to have to tip her.)","heroes":["h5","h4"],"parties":["p5"],"cause":"e452"},{"id":"e1021","day":27,"season":1,"sday":27,"kind":"party_life","imp":3,"text":"The Scarlet Gallopers turn back from the second floor of the Collapsed Mine because Rook has decided, firmly and without further detail, that the answer is no.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","refusal":"h15"},{"id":"e1022","day":27,"season":1,"sday":27,"kind":"delve_done","imp":3,"text":"The Scarlet Gallopers come out after 8 days, and the first thing anyone wants is bread. They reached the deepest floor, took 12 rooms off the map's blank side, mapped 87% of it, turned up the kobold lunch table, the new tunnels, the kobold shrine and 2 more good rooms, came away with 82 silver between them and turned back when one of them would go no further. Add up every party's sketches and the Collapsed Mine comes out mostly explored (87%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","days":8,"bottom":true,"rooms":["the kobold lunch table","the new tunnels"],"gold":82,"turn":"refused"},{"id":"e1060","day":28,"season":1,"sday":28,"kind":"road","imp":3,"text":"Captain Dorrit Salt teaches Pickles six sailor's knots on the verge, and one that is, she says, not for polite company.","heroes":["h4","h15","h5"],"parties":["p5"],"road":"collapsed_mine~veldrock","traveller":"salt","road_rec":"r237"},{"id":"e1105","day":29,"season":1,"sday":29,"kind":"party_life","imp":1,"text":"Pickles rides ahead, rides back, rides ahead again. Rook and Morwen are not amused.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"veldrock"},{"id":"e1125","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Morwen squeezes through a gap at the Collapsed Mine that nobody else will try, and comes back with a lantern and a grin. Spelunker, the way the old trappers taught it.","heroes":["h5"],"parties":["p5"],"loc":"collapsed_mine","skill":"spelunker"},{"id":"e1132","day":29,"season":1,"sday":29,"kind":"campfire","imp":1,"text":"Rook and Pickles wait out a hailstorm under one cart and play twenty questions with no winner.","heroes":["h15","h4"],"parties":["p5"],"loc":"collapsed_mine"},{"id":"e1155","day":30,"season":1,"sday":30,"kind":"delve","imp":1,"text":"The Scarlet Gallopers descend into the Collapsed Mine, mostly explored (87%), map in hand.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine"},{"id":"e1157","day":30,"season":1,"sday":30,"kind":"boss","imp":5,"text":"Morwen hits hardest while the Scarlet Gallopers bring down the Silk Matriarch, a Cave Troll and a Kobold at the bottom of the Collapsed Mine. Rook tied up the Silk Matriarch with Bear Trap at just the right moment. Morwen's Fire Arrow set the cave troll alight. Pickles saved Inspire for when it mattered. Morwen fought like someone with somewhere better to be afterwards. Rook insisted on checking every corner twice. Annoying. Correct. Loot: 14 silver each, 9 chitin, 2 gems.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","fight":"f74","foes":["spider_queen","cave_troll","kobold"],"where":"at the bottom of The Collapsed Mine","won":true,"close":false,"shape":"hero","reworded":-32},{"id":"e1158","day":30,"season":1,"sday":30,"kind":"treasure","imp":2,"text":"Nobody knew how much The Silk Matriarch had put by. The answer is 6 gold pieces and 8 silver, give or take what fell in the cracks.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","in_fight":"f74"},{"id":"e1159","day":30,"season":1,"sday":30,"kind":"gear","imp":4,"text":"Pickles carries a pair of gloves spun from something finer than silk from the silk-hung stope up out of the Collapsed Mine wrapped in a cloak. It hums. Someone in town will have to say why.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine"},{"id":"e1160","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"The silk-hung stope: the day's work on the bottom floor of the Collapsed Mine for The Scarlet Gallopers, taken at full stretch.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","pace":"push","stats":{"rooms":1,"empty":0,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":0,"wild":[]}},{"id":"e1161","day":30,"season":1,"sday":30,"kind":"delve_done","imp":1,"text":"The Scarlet Gallopers come up for air after a day, pockets heavier and boots wetter. They came across the silk-hung stope, went as deep as the place goes, took 1 room off the map's blank side and split 176 silver on the way up.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"collapsed_mine","days":1,"bottom":true,"rooms":["the silk-hung stope"],"gold":176,"turn":"done"},{"id":"e1168","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Pickles checks the horse's legs, then the saddle, then the horse's legs again, then eats.","heroes":["h4"],"parties":["p5"],"loc":"collapsed_mine","skill":"saddle_schooled"},{"id":"e1173","day":30,"season":1,"sday":30,"kind":"ledger","imp":2,"text":"Counters and coin this week: 9 sales, 535 silver changing hands. Biggest haul: Wren, 162 silver in Carrbridge. Back up from the deep: Verdant Edge (4 days in the Ashveil Crypts), The Scarlet Gallopers (1 day in the Collapsed Mine).","heroes":["h20","h12","h4"],"parties":["p8","p5"]},{"id":"e1174","day":30,"season":1,"sday":30,"kind":"big_move","imp":3,"text":"Morwen hits hardest while the Scarlet Gallopers bring down the Silk Matriarch, a Cave Troll and a Kobold at the bottom of the Collapsed Mine. On the table: The Scarlet Gallopers +97 party renown (5th to 2nd among the crews).","heroes":["h4","h15","h5"],"parties":["p5"],"party_moves":[{"party":"p5","gain":97,"from":5,"to":2}],"cause":"e1157","fight":"f74"},{"id":"e1180","day":30,"season":1,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Scarlet Gallopers set out to finish the season as one of the top three parties, and the final table says they made it. XP: Pickles +960 (level 12!), Rook +960 (level 13!), Morwen +960 (level 13!).","heroes":[],"parties":["p5"],"xp":{"h4":960,"h15":960,"h5":960}},{"id":"e1200","day":31,"season":2,"sday":1,"kind":"ability","imp":2,"text":"Morwen sniffs the air near Redcrag Hills, says 'tents, now', and an hour later the storm hits. Everyone is warm, dry and smug.","heroes":["h5"],"parties":["p5"],"loc":"redcrag","skill":"smells_the_weather","sk":"Smells the Weather","rule":true},{"id":"e1229","day":31,"season":2,"sday":1,"kind":"meet","imp":2,"text":"The Scarlet Gallopers and Red Hammers share a fire in Redcrag Hills. Rook and Bramble compare boots, then blisters, then regrets.","heroes":["h4","h15","h5","h13","h14"],"parties":["p5","p1"],"loc":"redcrag"},{"id":"e1232","day":31,"season":2,"sday":1,"kind":"ability","imp":1,"text":"Rook reads the crows circling over the next wood, says 'not today', and turns aside. Whatever was waiting in there waits for somebody else, and the party sleeps easy.","heroes":["h15"],"parties":["p5"],"loc":"redcrag","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e1234","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Morwen straightens a crooked inn sign near Redcrag Hills with one arrow through the chain link. The innkeeper waves. Trick Shot: a ranger's patience, mostly.","heroes":["h5"],"parties":["p5"],"loc":"redcrag","skill":"trick_shot"},{"id":"e1242","day":31,"season":2,"sday":1,"kind":"campfire","imp":3,"text":"A month in The Scarlet Gallopers: Pickles could pick Rook's footsteps out of a crowd now.","heroes":["h4","h15"],"parties":["p5"],"loc":"redcrag"},{"id":"e1251","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"The Scarlet Gallopers stand before the league and swear it: that no one leaves this party. The Annals are watching.","heroes":["h4","h15","h5"],"parties":["p5"]},{"id":"e1259","day":32,"season":2,"sday":2,"kind":"fight","imp":1,"text":"Riding a good week, the Scarlet Gallopers defeat 3 Claim-Jumpers in Redcrag Hills. Rook's last Caltrops settled it. Loot: 12 silver each, 4 bandit sausages, 5 ore.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"redcrag","fight":"f75","foes":["claim_jumper","claim_jumper","claim_jumper"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"mood","reworded":-20},{"id":"e1260","day":32,"season":2,"sday":2,"kind":"hunt","imp":3,"text":"Redcrag Hills: Following a trail into a gully, Rook finds a dead hunter's coat in the briars, long past use, and a purse in the lining. 5 silver, and a quiet moment before taking it.","heroes":["h15","h4","h5"],"parties":["p5"],"loc":"redcrag","road_rec":"r270"},{"id":"e1261","day":32,"season":2,"sday":2,"kind":"talent","imp":2,"text":"Morwen reads the tracks round camp at dawn: a fox, a badger, and Pickles sleepwalking. The pathfinder's trade has a name for that: Tracker.","heroes":["h5","h4"],"parties":["p5"],"loc":"redcrag","skill":"tracker"},{"id":"e1275","day":32,"season":2,"sday":2,"kind":"meet","imp":1,"text":"Gilded Wall and The Scarlet Gallopers share a fire in Redcrag Hills and trade news.","heroes":["h9","h6","h4","h15","h5"],"parties":["p6","p5"],"loc":"redcrag"},{"id":"e1288","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Pickles catches three trout before breakfast and cooks them on sticks. The crew wakes to the smell.","heroes":["h4"],"parties":["p5"],"loc":"redcrag","skill":"angler"},{"id":"e1300","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Morwen lays Rook's bedroll on the one dry patch of ground, without being asked. Smells the Weather all the way, Morwen insists.","heroes":["h5","h15"],"parties":["p5"],"loc":"redcrag","skill":"smells_the_weather"},{"id":"e1321","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"A month in The Scarlet Gallopers together. Pickles and Morwen know each other's snores, sorrows and orders by heart.","heroes":["h4","h5"],"parties":["p5"],"loc":"redcrag"},{"id":"e1322","day":33,"season":2,"sday":3,"kind":"campfire","imp":3,"text":"Rook and Morwen have shared a month of roads in The Scarlet Gallopers. Ask either one about the other and settle in for a story.","heroes":["h15","h5"],"parties":["p5"],"loc":"redcrag"},{"id":"e1335","day":34,"season":2,"sday":4,"kind":"ability","imp":2,"text":"Pickles lets the horse pick the pace past Ironhaven and spends the ride thinking. It does them good.","heroes":["h4"],"parties":["p5"],"loc":"ironhaven","skill":"saddle_schooled","sk":"Saddle-Schooled","rule":true},{"id":"e1367","day":35,"season":2,"sday":5,"kind":"road","imp":3,"text":"Mother Wort leads Pickles through a bramble tunnel, which the goblin calls the Quick Way. It is quick, in the sense of being mostly downhill.","heroes":["h4","h15","h5"],"parties":["p5"],"road":"ironhaven~thornwall","traveller":"muddy_boot","road_rec":"r292"},{"id":"e1383","day":35,"season":2,"sday":5,"kind":"talent","imp":2,"text":"Pickles draws a map of the region on the Thornwall tavern table with a wet finger. It's right. Saddle-Schooled: one of the things Pickles learned the long way round.","heroes":["h4"],"parties":["p5"],"loc":"thornwall","skill":"saddle_schooled"},{"id":"e1401","day":36,"season":2,"sday":6,"kind":"road","imp":3,"text":"Pickles follows Lady Perpetua Vane down the wrong road for half a day, because it would be rude not to.","heroes":["h4","h15","h5"],"parties":["p5"],"road":"kingsroad~thornwall","traveller":"perpetua","road_rec":"r295"},{"id":"e1416","day":36,"season":2,"sday":6,"kind":"ability","imp":2,"text":"Rook spots fresh boot-prints off the road, says nothing, and quietly picks another route. Pickles only works it out at supper, and sleeps better for it.","heroes":["h15","h4"],"parties":["p5"],"loc":"kingsroad","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e1499","day":38,"season":2,"sday":8,"kind":"talent","imp":2,"text":"Rook finds a shortcut through an orchard. The farmer waves.","heroes":["h15"],"parties":["p5"],"loc":"kingsroad","skill":"true_pathfinder"},{"id":"e1507","day":38,"season":2,"sday":8,"kind":"campfire","imp":1,"text":"A wagon gets stuck on the road. Rook and Pickles push it out together and refuse the farmer's coin.","heroes":["h15","h4"],"parties":["p5"],"loc":"kingsroad"},{"id":"e1530","day":39,"season":2,"sday":9,"kind":"hunt","imp":3,"text":"The King's Road: Rook has the doe in a clear line, sees the fawn behind it, and lowers the bow. A hunter's choice and nobody's rule. The two walk on, light on their feet.","heroes":["h15","h4","h5"],"parties":["p5"],"loc":"kingsroad","road_rec":"r313"},{"id":"e1531","day":39,"season":2,"sday":9,"kind":"ambush","imp":2,"text":"The Scarlet Gallopers wake to 2 Bandits and a Bandit Archer in camp on the King's Road in the middle of the night, and see them off. After Rook's Caltrops, the bandit hit like a tired farmhand. Morwen's Hold the Road was the quiet reason it went their way. Pickles went in first, as usual. Loot: 14 silver each, 1 bag of stolen goods, 2 rations.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"kingsroad","fight":"f92","foes":["bandit","bandit","bandit_archer"],"where":"at their camp in The King's Road, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-11},{"id":"e1559","day":40,"season":2,"sday":10,"kind":"party_life","imp":1,"text":"Rook and Morwen spend the whole road in the dust Pickles kicks up, and say so.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"kingsroad"},{"id":"e1560","day":40,"season":2,"sday":10,"kind":"ability","imp":2,"text":"Half a day in the saddle near Thornwall and Pickles has worked out where every stream runs. Something settles in them.","heroes":["h4"],"parties":["p5"],"loc":"thornwall","skill":"saddle_schooled","sk":"Saddle-Schooled","rule":true},{"id":"e1588","day":40,"season":2,"sday":10,"kind":"map_shared","imp":1,"text":"Over the same fire in Thornwall, The Scarlet Gallopers spread out a map of the Wolf Den and The Sunlit Almanac copies it room by room. Nobody asks for anything back.","heroes":["h4","h15","h5","h8","h20","h18","h19"],"parties":["p5","p4"],"loc":"thornwall","dungeon":"wolf_den","price":0},{"id":"e1632","day":41,"season":2,"sday":11,"kind":"talent","imp":2,"text":"Rook draws a better map of the region on a Carrbridge tavern table than the one on the wall.","heroes":["h15"],"parties":["p5"],"loc":"carrbridge","skill":"true_pathfinder"},{"id":"e1639","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"A Carrbridge stable boy asks Pickles for riding tips and gets an hour of them, free. Saddle-Schooled, the guild calls it.","heroes":["h4"],"parties":["p5"],"loc":"carrbridge","skill":"saddle_schooled"},{"id":"e1640","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"The Carrbridge farmers ask Morwen about the harvest weather and take notes. That's Smells the Weather for you.","heroes":["h5"],"parties":["p5"],"loc":"carrbridge","skill":"smells_the_weather"},{"id":"e1652","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Scarlet Gallopers' plan for the season, as told to the barkeep: to earn 2,050 silver between them before the season ends.","heroes":["h4","h15","h5"],"parties":["p5"]},{"id":"e1660","day":42,"season":2,"sday":12,"kind":"party_life","imp":1,"text":"Rook and Morwen ask Pickles if the view is nice up there. It is.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"carrbridge"},{"id":"e1705","day":43,"season":2,"sday":13,"kind":"party_life","imp":1,"text":"Rook and Morwen arrive at camp an hour behind Pickles and find the good spot by the fire taken.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashfen","wx":"rain"},{"id":"e1734","day":44,"season":2,"sday":14,"kind":"delve","imp":1,"text":"The Scarlet Gallopers descend into the Ashveil Crypts, mostly explored (81%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e1735","day":44,"season":2,"sday":14,"kind":"delve_day","imp":1,"text":"Ten rooms on the first floor of the Ashveil Crypts for The Scarlet Gallopers today: the mourners' porch, the sunken causeway, the gatehouse and 7 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":10,"empty":10,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1736","day":44,"season":2,"sday":14,"kind":"ability","imp":2,"text":"Morwen smells snow on the wind near the Ashveil Crypts and builds a windbreak of branches before dark. The snow comes. Morwen wakes warm and unbothered.","heroes":["h5"],"parties":["p5"],"loc":"ashveil_crypts","skill":"smells_the_weather","sk":"Smells the Weather","rule":true,"wx":"rain"},{"id":"e1756","day":44,"season":2,"sday":14,"kind":"talent","imp":1,"text":"Morwen knocks a pine cone off a branch in the dark, by sound alone. Rook demands to see it again.","heroes":["h5","h15"],"parties":["p5"],"loc":"ashveil_crypts","skill":"trick_shot","wx":"rain"},{"id":"e1775","day":45,"season":2,"sday":15,"kind":"delve_day","imp":1,"text":"Deeper into the first floor of the Ashveil Crypts: The Scarlet Gallopers see eight rooms today, at a steady pace (the embalming room, the gravediggers' bunks, the widows' walk and 5 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":8,"empty":8,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1801","day":46,"season":2,"sday":16,"kind":"delve_day","imp":1,"text":"The Scarlet Gallopers push on through the second floor of the Ashveil Crypts steadily. Seven rooms by nightfall: the grave-goods store, the chantry, the mason's yard and 4 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":7,"empty":6,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1802","day":46,"season":2,"sday":16,"kind":"night","imp":2,"text":"Something small and clever gets into The Scarlet Gallopers' camp on the second floor of the Ashveil Crypts overnight. Rook wakes up 3 silver and 1 ration lighter.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e1804","day":46,"season":2,"sday":16,"kind":"talent","imp":1,"text":"Morwen chalks arrows at every turn at the Ashveil Crypts. The way out is never in doubt.","heroes":["h5"],"parties":["p5"],"loc":"ashveil_crypts","skill":"trailblazer","wx":"rain"},{"id":"e1822","day":47,"season":2,"sday":17,"kind":"delve_day","imp":1,"text":"Down in the Ashveil Crypts, The Scarlet Gallopers map seven rooms of the second floor, without hurrying (the family archive, the sexton's lodging, The Ninth Step and 4 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":7,"empty":6,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1823","day":47,"season":2,"sday":17,"kind":"talent","imp":2,"text":"Rook picks a campsite with a view, a stream and no mosquitoes. Nobody knows how.","heroes":["h15"],"parties":["p5"],"loc":"ashveil_crypts","skill":"true_pathfinder","wx":"fog"},{"id":"e1824","day":47,"season":2,"sday":17,"kind":"night","imp":2,"text":"Pickles tells a ghost story by the fire on the second floor of the Ashveil Crypts. Rook laughs at it, then moves their bedroll closer to the others.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1851","day":48,"season":2,"sday":18,"kind":"fight","imp":2,"text":"The Scarlet Gallopers send 3 Skeleton Archers, a Bone Construct and Risen Dead back to their rest in the stitching room on the second floor of the Ashveil Crypts. Pickles ended it the plain way: Feint, and the risen dead on the ground. Loot: 23 bones, 3 crypt-caps, 2 grave dust. Rook hates the dead more than anything, and fights through it anyway.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f107","foes":["skeleton_archer","skeleton_archer","skeleton_archer"],"where":"in the stitching room on the second floor of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-16,"wx":"fog"},{"id":"e1852","day":48,"season":2,"sday":18,"kind":"delve_day","imp":1,"text":"The Scarlet Gallopers spend the day on the second floor of the Ashveil Crypts, one door at a time, and cover five rooms: the reliquary, the embalming room, the funeral feast hall and 2 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":5,"empty":2,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"fog"},{"id":"e1876","day":49,"season":2,"sday":19,"kind":"gear","imp":1,"text":"In a walled-up room beside the stitching room on the second floor of the Ashveil Crypts, Rook finds a Keen Fine Cloak and puts it on. Keen: a steadier aim (+2 aim).","heroes":["h15"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e1877","day":49,"season":2,"sday":19,"kind":"delve_day","imp":1,"text":"The Scarlet Gallopers give the deepest floor of the Ashveil Crypts another day, at a steady pace, and six rooms give way (a walled-up room beside the stitching room, the drowned niches, the Veyne vault and 3 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":6,"empty":5,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":0,"wild":[]}},{"id":"e1878","day":49,"season":2,"sday":19,"kind":"ability","imp":2,"text":"Morwen moves camp at the Ashveil Crypts to higher ground for no reason anyone can see. The stream floods at midnight. Nobody's boots get wet.","heroes":["h5"],"parties":["p5"],"loc":"ashveil_crypts","skill":"smells_the_weather","sk":"Smells the Weather","rule":true},{"id":"e1910","day":49,"season":2,"sday":19,"kind":"campfire","imp":1,"text":"After the fight, Pickles and Morwen sit back to back on a rock and don't say anything for a long time.","heroes":["h4","h5"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e1928","day":50,"season":2,"sday":20,"kind":"fight","imp":1,"text":"Rook hits hardest as the Scarlet Gallopers dispatch a Wraith in the colonnade of the hour on the deepest floor of the Ashveil Crypts. Morwen's Aimed Shot took most of the fight out of the wraith in one go. Rook did the unglamorous work that kept the line from breaking. Loot: 4 ectoplasm, 2 wraith-frost.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f112","foes":["wraith"],"where":"in the colonnade of the hour on the deepest floor of the Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-21},{"id":"e1929","day":50,"season":2,"sday":20,"kind":"delve_day","imp":1,"text":"Chalk marks on six rooms of the deepest floor of the Ashveil Crypts say The Scarlet Gallopers have been through, steadily (the articulator's hall, the long gallery, the iron-bound door and 3 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":6,"empty":4,"size":3,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e1941","day":50,"season":2,"sday":20,"kind":"talent","imp":1,"text":"Rook holds the wooden charm while falling asleep. He sleeps well.","heroes":["h15"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e1952","day":51,"season":2,"sday":21,"kind":"party_life","imp":3,"text":"Rook gripped the doorframe on the third floor like a person at sea, and The Scarlet Gallopers turn home rather than prise Rook off it.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","refusal":"h15","wx":"rain"},{"id":"e1953","day":51,"season":2,"sday":21,"kind":"delve_done","imp":3,"text":"The Scarlet Gallopers come up for air after 8 days, pockets heavier and boots wetter. They reached the deepest floor, mapped 87% of it, turned up the reliquary, a walled-up room beside the stitching room and the colonnade of the hour, cleared 8 rooms, came away with 168 silver between them and turned back when one of them would go no further. The Ashveil Crypts, all crews together: picked clean (93%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","days":8,"bottom":true,"rooms":["the reliquary","a walled-up room beside the stitching room"],"gold":168,"turn":"refused","wx":"rain"},{"id":"e1954","day":51,"season":2,"sday":21,"kind":"night","imp":2,"text":"Someone leaves a scrap of map by The Scarlet Gallopers' fire outside the Ashveil Crypts in the night. It shows a door in the Collapsed Mine that isn't on any other map.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e2023","day":53,"season":2,"sday":23,"kind":"ability","imp":2,"text":"Pickles rides the long way round Bleakmarsh on purpose, reading the land like a page, and arrives calmer and wiser.","heroes":["h4"],"parties":["p5"],"loc":"bleakmarsh","skill":"saddle_schooled","sk":"Saddle-Schooled","rule":true},{"id":"e2038","day":54,"season":2,"sday":24,"kind":"ability","imp":1,"text":"Morwen pitches camp at Bleakmarsh under an overhang on a cloudless evening. Hail the size of peas falls all night. Morwen sleeps through it, smug and dry.","heroes":["h5"],"parties":["p5"],"loc":"bleakmarsh","skill":"smells_the_weather","sk":"Smells the Weather","rule":true,"wx":"rain"},{"id":"e2104","day":55,"season":2,"sday":25,"kind":"ability","imp":2,"text":"A broken twig, a gate left open, a farm dog that won't bark: Rook reads all three and goes round. Nothing at all happens on the road today, which was the idea.","heroes":["h15"],"parties":["p5"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"rain"},{"id":"e2106","day":55,"season":2,"sday":25,"kind":"talent","imp":2,"text":"Pickles rides ahead, rides back, and draws the next three miles in the dirt for everyone. Saddle-Schooled: one of the things Pickles learned the long way round.","heroes":["h4"],"parties":["p5"],"loc":"bleakmarsh","skill":"saddle_schooled","wx":"rain"},{"id":"e2131","day":56,"season":2,"sday":26,"kind":"talent","imp":1,"text":"Rook stops at a quiet bend, frowns, and takes the long way. Later word comes of what was waiting there.","heroes":["h15"],"parties":["p5"],"loc":"bleakmarsh","skill":"true_pathfinder","wx":"rain"},{"id":"e2136","day":56,"season":2,"sday":26,"kind":"campfire","imp":1,"text":"A wagon gets stuck on the road. Rook and Morwen push it out together and refuse the farmer's coin.","heroes":["h15","h5"],"parties":["p5"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2199","day":58,"season":2,"sday":28,"kind":"road","imp":3,"text":"Rook hears the Lantern Lady say that she cannot remember her own name, only that it is written somewhere. Rook promises to look.","heroes":["h15","h4","h5"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"lantern_lady","road_rec":"r467"},{"id":"e2246","day":59,"season":2,"sday":29,"kind":"road","imp":3,"text":"Rook helps Tansy Fell clear a barn. The ferrets do the work. Rook holds the sack and the lamp, and is thanked like a partner.","heroes":["h15","h4","h5"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"tansy","road_rec":"r474"},{"id":"e2272","day":60,"season":2,"sday":30,"kind":"ability","imp":2,"text":"Pickles rides past Bleakmarsh with Morwen and explains the lie of the land. Both of them come away the better for it.","heroes":["h4","h5"],"parties":["p5"],"loc":"bleakmarsh","skill":"saddle_schooled","sk":"Saddle-Schooled","rule":true,"wx":"fog"},{"id":"e2273","day":60,"season":2,"sday":30,"kind":"ability","imp":1,"text":"Pickles wants to camp in the pretty meadow at Bleakmarsh. Morwen says the meadow will be a pond by morning. It is. The crew watches it fill from a dry hill, very cheerful.","heroes":["h5","h4"],"parties":["p5"],"loc":"bleakmarsh","skill":"smells_the_weather","sk":"Smells the Weather","rule":true,"wx":"fog"},{"id":"e2300","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Season's end, and The Scarlet Gallopers came up short: earn 2,050 silver between them before the season ends (485 of 2,050 silver).","heroes":["h4","h15","h5"],"parties":["p5"]},{"id":"e2321","day":61,"season":3,"sday":1,"kind":"road","imp":4,"text":"At a crossroads, Jory Bellwether proclaims the name of Morwen to the four winds, with a bow for each wind. It carries a surprisingly long way.","heroes":["h5","h15","h4"],"parties":["p5"],"road":"carrbridge~ironhaven","traveller":"jory","road_rec":"r483"},{"id":"e2352","day":61,"season":3,"sday":1,"kind":"boss_race","imp":3,"text":"Mother Thornmere's Brood has visitors coming. The Scarlet Gallopers and Verdant Edge are both on the way to Thornmere Ruins, and nobody is waiting for the others.","heroes":["h4","h15","h5","h12","h17"],"parties":["p5","p8"],"loc":"thornmere_ruins"},{"id":"e2356","day":61,"season":3,"sday":1,"kind":"gift","imp":2,"text":"Rook gives Morwen a Hand-Carved Charm. \"For luck,\" Rook says, and won't explain further.","heroes":["h15","h5"],"parties":["p5"],"loc":"carrbridge","wx":"heat"},{"id":"e2395","day":62,"season":3,"sday":2,"kind":"meet","imp":2,"text":"The Scarlet Gallopers and Verdant Edge share a fire in Bleakmarsh. There is a short argument about the best road to Carrbridge.","heroes":["h4","h15","h5","h12","h17"],"parties":["p5","p8"],"loc":"bleakmarsh"},{"id":"e2428","day":64,"season":3,"sday":4,"kind":"delve","imp":1,"text":"The Scarlet Gallopers descend into Thornmere Ruins, untouched (0%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2429","day":64,"season":3,"sday":4,"kind":"fight","imp":2,"text":"In the reed beds on the first floor of Thornmere Ruins, the Scarlet Gallopers square up to 2 Bog Crawlers and 2 Will-o'-Wisps and carry the day. Four of them felt Rook's Caltrops in the same breath. Look past the blows: Morwen's Hold the Road was the difference. Loot: 2 bog crawler claws, 4 wisp sugar, 2 chitin.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f141","foes":["bog_crawler","wisp","bog_crawler"],"where":"in the reed beds on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-24,"wx":"rain"},{"id":"e2430","day":64,"season":3,"sday":4,"kind":"delve_day","imp":1,"text":"The Scarlet Gallopers work the first floor of Thornmere Ruins at speed: three rooms (the reed beds, a walled-up room beside the reed beds, the sunken stair).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":1,"wild":[]},"wx":"rain"},{"id":"e2431","day":64,"season":3,"sday":4,"kind":"night","imp":2,"text":"A woman with a lantern and no luggage walks into The Scarlet Gallopers' camp on the first floor of Thornmere Ruins, asks the way to Goblin Camp, and leaves the firelight in the wrong direction.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2451","day":64,"season":3,"sday":4,"kind":"campfire","imp":1,"text":"Pickles saves Morwen the crispy bits from the pan without a word.","heroes":["h5","h4"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2475","day":65,"season":3,"sday":5,"kind":"fight","imp":2,"text":"The Scarlet Gallopers beat 2 Swamp Trolls, a Bog Crawler and a Will-o'-Wisp in the drowned nave on the first floor of Thornmere Ruins. Morwen loosed Game Shot, and the swamp troll dropped. Loot: 33 silver each, 3 chitin, 2 bog crawler claws.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f146","foes":["bog_crawler","swamp_troll","swamp_troll"],"where":"in the drowned nave on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"plain"},{"id":"e2476","day":65,"season":3,"sday":5,"kind":"delve_day","imp":1,"text":"It's the first floor of Thornmere Ruins today, and The Scarlet Gallopers work through it at a hard pace: seven rooms (the porters' lodge, the pilgrims' hall, the reed stair and 4 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":7,"empty":5,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e2477","day":65,"season":3,"sday":5,"kind":"ability","imp":2,"text":"Pickles laughs when Morwen digs a rain trench by Thornmere Ruins under a clear sky. Pickles stops laughing at three in the morning, dry and grateful.","heroes":["h5","h4"],"parties":["p5"],"loc":"thornmere_ruins","skill":"smells_the_weather","sk":"Smells the Weather","rule":true},{"id":"e2489","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"By lamplight on the first floor of Thornmere Ruins, The Scarlet Gallopers clear the way through two rooms, one door at a time: the flooded side aisle, the wayside cross.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2501","day":66,"season":3,"sday":6,"kind":"rescue","imp":4,"text":"Ash (Morgan's hero) owes Pickles (Jordan's hero) a life now: The Scarlet Gallopers pulled Verdant Edge out of trouble in Thornmere Ruins, 2 potions poorer.","heroes":["h4","h12","h15","h5","h17"],"parties":["p5","p8"],"loc":"thornmere_ruins","rescuers":["h4","h15","h5"]},{"id":"e2511","day":66,"season":3,"sday":6,"kind":"map_shared","imp":1,"text":"The Scarlet Gallopers draw Verdant Edge a rough copy of the Ashveil Crypts on the back of a ration wrapper, as far as the second floor. Friends do that.","heroes":["h4","h15","h5","h12","h17"],"parties":["p5","p8"],"loc":"thornmere_ruins","dungeon":"ashveil_crypts","price":0},{"id":"e2525","day":67,"season":3,"sday":7,"kind":"fight","imp":2,"text":"Riding a good week, the Scarlet Gallopers make short work of 4 Bog Crawlers in the tithe barn on the first floor of Thornmere Ruins. The last bog crawler has seen enough, and goes while it can. Somewhere around Morwen's Called Shot, the other side stopped believing. Loot: 9 chitin, 2 bog crawler claws.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f152","foes":["bog_crawler","bog_crawler","bog_crawler"],"where":"in the tithe barn on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"mood","reworded":-53},{"id":"e2526","day":67,"season":3,"sday":7,"kind":"fight","imp":2,"text":"Two Bog Crawlers and a Swamp Troll fall to the Scarlet Gallopers in the sunken stair behind the font on the first floor of Thornmere Ruins. Bear Trap from Rook left the swamp troll reeling. Loot: 15 silver each, 5 chitin, 2 bog crawler claws.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f153","foes":["bog_crawler","bog_crawler","swamp_troll"],"where":"in the sunken stair behind the font on the first floor of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-1},{"id":"e2527","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"Four rooms on the first floor of Thornmere Ruins for The Scarlet Gallopers today: the tithe barn, the sunken stair behind the font, the reliquary niche and 1 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e2549","day":67,"season":3,"sday":7,"kind":"talent","imp":1,"text":"Rook does an owl so well that a real owl lands on the tent. Morwen is speechless.","heroes":["h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","skill":"bird_caller"},{"id":"e2550","day":67,"season":3,"sday":7,"kind":"campfire","imp":2,"text":"Morwen and Pickles share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h5","h4"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2558","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"Another day under Thornmere Ruins: The Scarlet Gallopers walk two rooms of the first floor, with a look round every corner (the priests' cells, a sealed space off the priests' cells).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"empty":0,"size":3,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e2585","day":68,"season":3,"sday":8,"kind":"campfire","imp":1,"text":"Pickles mends Morwen's bootlace with a bit of string and a great deal of confidence.","heroes":["h4","h5"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2600","day":69,"season":3,"sday":9,"kind":"gear","imp":1,"text":"In the confession box on the second floor of Thornmere Ruins, Morwen finds a Fen-Proofed Ranger's Hood and puts it on. Fen-Proofed: tougher (+4% health).","heroes":["h5"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2601","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The Scarlet Gallopers tally up the second floor of Thornmere Ruins at nightfall: three rooms, taken at a steady pace, and the names go in the book (the font that still fills, the confession box, the granary).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":3,"empty":0,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":2,"wild":[]}},{"id":"e2602","day":69,"season":3,"sday":9,"kind":"talent","imp":2,"text":"Rook preaches to the crew about sharing. Pickles hands over the last biscuit, shamed.","heroes":["h15","h4"],"parties":["p5"],"loc":"thornmere_ruins","skill":"sermoniser"},{"id":"e2634","day":70,"season":3,"sday":10,"kind":"trap","imp":2,"text":"Pickles springs a tripwire in the curtain of hair on the second floor of Thornmere Ruins (bruised ribs).","heroes":["h4"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2635","day":70,"season":3,"sday":10,"kind":"delve_day","imp":1,"text":"A long day on the second floor of Thornmere Ruins. The Scarlet Gallopers come through four rooms, without hurrying: the granary, The Lantern That Waits, the reliquary niche and 1 more.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"empty":0,"size":3,"floor":2,"traps":2,"sprung":2,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2636","day":70,"season":3,"sday":10,"kind":"ability","imp":2,"text":"Morwen sniffs the air near Thornmere Ruins, says 'tents, now', and an hour later the storm hits. Everyone is warm, dry and smug.","heroes":["h5"],"parties":["p5"],"loc":"thornmere_ruins","skill":"smells_the_weather","sk":"Smells the Weather","rule":true},{"id":"e2662","day":71,"season":3,"sday":11,"kind":"party_life","imp":3,"text":"The second floor was enough for Rook, who sat down cross-legged and asked to be collected on the way back. There was no way back without Rook, so The Scarlet Gallopers turn for the stairs.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","refusal":"h15"},{"id":"e2663","day":71,"season":3,"sday":11,"kind":"delve_done","imp":3,"text":"Thornmere Ruins gives up The Scarlet Gallopers after 8 days, a little reluctantly, like a cat letting go of a sock. They got down to the second floor, worked through 20 rooms, mapped 42% of it, found a walled-up room beside the reed beds, the reliquary niche, a sealed space off the priests' cells and 2 more good rooms, came away with 383 silver between them and turned back when one of them would go no further. The guild's map has it: Thornmere Ruins is partly explored (38%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","days":8,"bottom":false,"rooms":["a walled-up room beside the reed beds","the reliquary niche"],"gold":383,"turn":"refused"},{"id":"e2664","day":71,"season":3,"sday":11,"kind":"night","imp":2,"text":"A child turns up at The Scarlet Gallopers' camp outside Thornmere Ruins, announces that Emberdeep \"eats lanterns\", and runs off before anyone can ask what that means.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e2701","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Scarlet Gallopers set their sights for the season: to finish the season as one of the top three parties.","heroes":["h4","h15","h5"],"parties":["p5"]},{"id":"e2729","day":72,"season":3,"sday":12,"kind":"night","imp":2,"text":"Pickles follows strange lights away from the camp in Bleakmarsh, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e2735","day":72,"season":3,"sday":12,"kind":"meet","imp":1,"text":"Red Hammers and The Scarlet Gallopers share a fire in Bleakmarsh. Ottoline shares a bad map.","heroes":["h13","h14","h4","h15","h5"],"parties":["p1","p5"],"loc":"bleakmarsh"},{"id":"e2737","day":72,"season":3,"sday":12,"kind":"ability","imp":2,"text":"Rook reads the crows circling over the next wood, says 'not today', and turns aside. Whatever was waiting in there waits for somebody else, and the party sleeps easy.","heroes":["h15"],"parties":["p5"],"loc":"bleakmarsh","skill":"true_pathfinder","sk":"True Pathfinder","rule":true},{"id":"e2814","day":74,"season":3,"sday":14,"kind":"boss_race","imp":2,"text":"The Scarlet Gallopers are out of the race for Mother Thornmere's Brood: they have gone hunting in the Greenwood. That leaves Red Hammers and Verdant Edge.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e2819","day":74,"season":3,"sday":14,"kind":"bond","imp":3,"text":"The Scarlet Gallopers and The Sunlit Almanac are rivals now, starting with Rook and Barnaby.","heroes":["h15","h19"],"parties":["p5","p4"],"loc":"carrbridge","bond":"rivals"},{"id":"e2864","day":75,"season":3,"sday":15,"kind":"talent","imp":1,"text":"Morwen finds a Thornwall farmer's lost goat by following it through three gardens. Reward: cheese and silver.","heroes":["h5"],"parties":["p5"],"loc":"thornwall","skill":"tracker"},{"id":"e2882","day":76,"season":3,"sday":16,"kind":"road","imp":3,"text":"Wenna lets Pickles in on the secret: the squeak is deliberate. Customers hear her coming and have the coppers ready.","heroes":["h4","h15","h5"],"parties":["p5"],"road":"greenwood~thornwall","traveller":"wenna","road_rec":"r609"},{"id":"e2883","day":76,"season":3,"sday":16,"kind":"ability","imp":2,"text":"Morwen smells snow on the wind near the Greenwood and builds a windbreak of branches before dark. The snow comes. Morwen wakes warm and unbothered.","heroes":["h5"],"parties":["p5"],"loc":"greenwood","skill":"smells_the_weather","sk":"Smells the Weather","rule":true,"wx":"storm"},{"id":"e2919","day":77,"season":3,"sday":17,"kind":"fight","imp":2,"text":"The Scarlet Gallopers defeat 4 Bugbears in the Greenwood, in the middle of a storm. The bugbear went down to Morwen's Called Shot. Pickles's Wheel About kicked in when it counted. Loot: 9 silver each, 6 goblin ears, 1 trinket.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"greenwood","fight":"f167","foes":["bugbear","bugbear","bugbear"],"where":"in The Greenwood","won":true,"close":false,"shape":"weather","reworded":-26,"wx":"storm"},{"id":"e2920","day":77,"season":3,"sday":17,"kind":"night","imp":1,"text":"Pickles tells a ghost story by the fire in the Greenwood. Rook insists on keeping the fire going until dawn. For warmth.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"greenwood","wx":"storm"},{"id":"e2926","day":77,"season":3,"sday":17,"kind":"gift","imp":2,"text":"Pickles gives Rook a Hand-Carved Charm. \"For luck,\" Pickles says, and won't explain further.","heroes":["h4","h15"],"parties":["p5"],"loc":"greenwood","wx":"storm"},{"id":"e2928","day":77,"season":3,"sday":17,"kind":"ability","imp":1,"text":"Rook hears a bridge creak wrong, walks the long way round, and is proven right by a loud splash behind them. It is not their splash.","heroes":["h15"],"parties":["p5"],"loc":"greenwood","skill":"true_pathfinder","sk":"True Pathfinder","rule":true,"wx":"storm"},{"id":"e2950","day":78,"season":3,"sday":18,"kind":"fight","imp":2,"text":"Back in the Greenwood, the Scarlet Gallopers defeat 3 Dire Wolves and a Wolf. The hit of the day was Rook's Thorn Whip on the wolf. Loot: 9 pelts, 6 fangs & claws, 2 wolf haunches.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"greenwood","fight":"f169","foes":["dire_wolf","dire_wolf","dire_wolf"],"where":"in The Greenwood","won":true,"close":false,"shape":"again","reworded":-6,"wx":"storm"},{"id":"e2960","day":78,"season":3,"sday":18,"kind":"talent","imp":1,"text":"Morwen says it'll rain at four. It rains at four. Morwen has an umbrella. Chalk it up to Smells the Weather.","heroes":["h5"],"parties":["p5"],"loc":"greenwood","skill":"smells_the_weather","wx":"storm"},{"id":"e2967","day":78,"season":3,"sday":18,"kind":"campfire","imp":1,"text":"Rook aims an arrow at a far-off crow, misses on purpose, and gets a laugh out of Morwen.","heroes":["h15","h5"],"parties":["p5"],"loc":"greenwood","wx":"storm"},{"id":"e3039","day":80,"season":3,"sday":20,"kind":"gift","imp":2,"text":"The Hand-Carved Charm changes hands again: Morwen to Pickles this time. It has been passed around this crew 2 times now.","heroes":["h5","h4"],"parties":["p5"],"loc":"carrbridge","wx":"rain"},{"id":"e3047","day":80,"season":3,"sday":20,"kind":"campfire","imp":2,"text":"Pickles saves Rook the good spot by the fire. Again.","heroes":["h4","h15"],"parties":["p5"],"loc":"carrbridge","wx":"rain"},{"id":"e3078","day":81,"season":3,"sday":21,"kind":"talent","imp":1,"text":"A farmer's bull blocks the lane near Bleakmarsh. Rook talks to it, low and steady. The bull moves. Chalk it up to Animal Handler.","heroes":["h15"],"parties":["p5"],"loc":"bleakmarsh","skill":"animal_handler","wx":"fog"},{"id":"e3082","day":81,"season":3,"sday":21,"kind":"talent","imp":1,"text":"Morwen explains, at length, the difference between a cave and a cavern. Nobody asked. Pickles is now interested. Spelunker: a ranger's patience, mostly.","heroes":["h5","h4"],"parties":["p5"],"loc":"bleakmarsh","skill":"spelunker","wx":"fog"},{"id":"e3103","day":82,"season":3,"sday":22,"kind":"ability","imp":2,"text":"Morwen moves camp at Bleakmarsh to higher ground for no reason anyone can see. The stream floods at midnight. Nobody's boots get wet.","heroes":["h5"],"parties":["p5"],"loc":"bleakmarsh","skill":"smells_the_weather","sk":"Smells the Weather","rule":true,"wx":"fog"},{"id":"e3144","day":83,"season":3,"sday":23,"kind":"fight","imp":1,"text":"In Bleakmarsh, the Scarlet Gallopers square up to a Bog Crawler and a Giant Spider and carry the day. The last giant spider slips away while nobody is looking. Morwen's Hold the Road came at the right time for all of them. Loot: 3 chitin, 2 bog crawler claws.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"bleakmarsh","fight":"f177","foes":["bog_crawler","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-54},{"id":"e3147","day":83,"season":3,"sday":23,"kind":"fight","imp":2,"text":"With Morwen hitting hardest, the Scarlet Gallopers make short work of 2 Giant Spiders and 2 Bog Crawlers in Bleakmarsh. The last giant spider looks at the odds and leaves. Morwen picked out the bog crawler and finished the job with Called Shot. Loot: 11 chitin, 2 spider legs.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"bleakmarsh","fight":"f178","foes":["giant_spider","bog_crawler","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-52},{"id":"e3152","day":83,"season":3,"sday":23,"kind":"meet","imp":1,"text":"Verdant Edge and The Scarlet Gallopers share a fire in Bleakmarsh. Nobody draws steel, which counts as a good meeting these days.","heroes":["h12","h17","h4","h15","h5"],"parties":["p8","p5"],"loc":"bleakmarsh"},{"id":"e3158","day":83,"season":3,"sday":23,"kind":"campfire","imp":1,"text":"Pickles and Rook race to the next milestone. Rook wins, and Pickles claims a technical foul.","heroes":["h4","h15"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e3168","day":84,"season":3,"sday":24,"kind":"ability","imp":2,"text":"Half a day in the saddle near Carrbridge and Pickles has worked out where every stream runs. Something settles in him.","heroes":["h4"],"parties":["p5"],"loc":"carrbridge","skill":"saddle_schooled","sk":"Saddle-Schooled","rule":true},{"id":"e3170","day":84,"season":3,"sday":24,"kind":"gift","imp":2,"text":"Morwen hands her old Fen-Proofed Ranger's Hood to Rook, who has been eyeing it for a week.","heroes":["h5","h15"],"parties":["p5"],"loc":"carrbridge"},{"id":"e3171","day":84,"season":3,"sday":24,"kind":"wagon","imp":3,"text":"The Scarlet Gallopers roll out of Carrbridge in an ox wagon called The Creak, 64 silver between them. Who paid: Pickles 56, Rook 7, Morwen 1.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"carrbridge"},{"id":"e3226","day":85,"season":3,"sday":25,"kind":"talent","imp":2,"text":"Pickles overhears two merchants at the Thornwall tavern discussing a price rise, and gets in first.","heroes":["h4"],"parties":["p5"],"loc":"thornwall","skill":"eavesdropper"},{"id":"e3230","day":85,"season":3,"sday":25,"kind":"journey","imp":2,"text":"Verdant Edge and The Scarlet Gallopers fall in together on the road to Thornwall and spend the miles arguing about Fenwick's terrible singing.","heroes":["h12","h17","h4","h15","h5"],"parties":["p8","p5"]},{"id":"e3237","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Pickles trims Rook's hair at The Sagging Beam with a borrowed knife. The result is described as brave.","heroes":["h15","h4"],"parties":["p5"],"loc":"thornwall"},{"id":"e3266","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Pickles bets the Carrbridge tavern he can mount a horse backwards from the bar. He can.","heroes":["h4"],"parties":["p5"],"loc":"carrbridge","skill":"trick_rider"},{"id":"e3299","day":87,"season":3,"sday":27,"kind":"talent","imp":1,"text":"An Ashfen carter pays Morwen to ride shotgun to the next village. The road is empty. The carter is delighted by this.","heroes":["h5"],"parties":["p5"],"loc":"ashfen","skill":"road_patrol"},{"id":"e3324","day":88,"season":3,"sday":28,"kind":"ability","imp":2,"text":"Pickles watches how the horse takes the hill near the Ashveil Crypts and learns more about footing than any book taught.","heroes":["h4"],"parties":["p5"],"loc":"ashveil_crypts","skill":"saddle_schooled","sk":"Saddle-Schooled","rule":true,"wx":"rain"},{"id":"e3344","day":88,"season":3,"sday":28,"kind":"music","imp":3,"text":"The Scarlet Gallopers sang \"The Ranger's Promise\" under a clear sky last night, and somewhere in the chorus it became their anthem. Ask any of them; they'll sing it for you.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","anthem":"rangers_promise","night":"n220","wx":"rain"},{"id":"e3360","day":89,"season":3,"sday":29,"kind":"delve","imp":1,"text":"The Scarlet Gallopers descend into the Ashveil Crypts, partly explored (41%), map in hand.","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e3361","day":89,"season":3,"sday":29,"kind":"delve_day","imp":1,"text":"Deeper into the first floor of the Ashveil Crypts: The Scarlet Gallopers see two rooms today, steadily (the reliquary passage, the chantry).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"empty":0,"size":3,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e3384","day":89,"season":3,"sday":29,"kind":"gift","imp":2,"text":"The Hand-Carved Charm changes hands again: Rook to Morwen this time. It has been passed around this crew 2 times now.","heroes":["h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e3389","day":89,"season":3,"sday":29,"kind":"campfire","imp":3,"text":"Rook and Pickles take the late watch together and argue happily about the best road to Ironhaven.","heroes":["h15","h4"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e3405","day":90,"season":3,"sday":30,"kind":"gear","imp":1,"text":"In a walled-up room beside the family archive on the second floor of the Ashveil Crypts, Morwen finds a Keen Boiled-Leather Cap, and stashes it to sell. Keen: a steadier aim (+2 aim).","heroes":["h5"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e3406","day":90,"season":3,"sday":30,"kind":"delve_day","imp":1,"text":"Chalk marks on five rooms of the second floor of the Ashveil Crypts say The Scarlet Gallopers have been through, slowly, chalking every door (the chapel of the weeping saint, the chapel of statues, the candle vault and 2 more).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":5,"empty":4,"size":3,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"rain"},{"id":"e3407","day":90,"season":3,"sday":30,"kind":"talent","imp":2,"text":"Pickles checks the horse's legs, then the saddle, then the horse's legs again, then eats. Chalk it up to Saddle-Schooled.","heroes":["h4"],"parties":["p5"],"loc":"ashveil_crypts","skill":"saddle_schooled","wx":"rain"},{"id":"e3414","day":90,"season":3,"sday":30,"kind":"talent","imp":1,"text":"Rook stitches a torn sleeve closed mid-delve at the Ashveil Crypts, holding the thread in their teeth.","heroes":["h15"],"parties":["p5"],"loc":"ashveil_crypts","skill":"tailor","wx":"rain"},{"id":"e3419","day":90,"season":3,"sday":30,"kind":"campfire","imp":1,"text":"Rook patches Morwen's cloak without being asked. Morwen pretends not to notice, then says thanks.","heroes":["h5","h15"],"parties":["p5"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e3427","day":90,"season":3,"sday":30,"kind":"delve_done","imp":3,"text":"The Scarlet Gallopers come out after 2 days, and the first thing anyone wants is bread. They made it to the second floor, worked through 3 rooms, turned up the chantry and a walled-up room beside the family archive, inked 47% of the map and came away with 96 silver between them. Add up every party's sketches and the Ashveil Crypts comes out partly explored (44%).","heroes":["h4","h15","h5"],"parties":["p5"],"loc":"ashveil_crypts","days":2,"bottom":false,"rooms":["the chantry","a walled-up room beside the family archive"],"gold":96,"wx":"rain"},{"id":"e3435","day":90,"season":3,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Scarlet Gallopers set out to finish the season as one of the top three parties, and the final table says they made it. XP: Pickles +800 (level 19!), Rook +960, Morwen +960.","heroes":[],"parties":["p5"],"xp":{"h4":800,"h15":960,"h5":960}},{"id":"e3449","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Vigil of Carrbridge, to keep the peace: never draw first on another hero (sworn in season 2); The Amber Sigil, never to retreat (sworn in season 2); The Sunlit Almanac, to keep the peace: never draw first on another hero (sworn in season 2); The Scarlet Gallopers, that no one leaves this party (sworn in season 2); Gilded Wall, never to leave a companion behind (sworn in season 2); Verdant Edge, to share every coin (sworn in season 2); Duren, never to pay a toll (sworn in season 1). Every one of them held.","heroes":["h3"],"parties":["p2","p3","p4","p5","p6","p8"]}],"roles":{"h4":"Leader · Point","h15":"Trail-reader","h5":"Blade"},"quest":{"what":"Delve","where":"The Ashveil Crypts","why":"the boss is back: about 39 silver a day each, risk slight; itching to get underground again; the season goal: to finish the season as one of the top three parties","floor":1,"floors":3},"tactics":{"front":[],"back":["h4","h15","h5"],"plan":"Pickles, Rook and Morwen pick off whatever gets close.","traits":{"boldness":0.12,"risk":-0.39,"greed":-0.1,"sociability":0.08,"honor":0.34,"curiosity":-0.4,"temper":-0.04,"loyalty":0.01},"mix":"3 bows","notes":["Nobody wants the front row. Whoever's nearest takes the hits.","No healer: every wound comes home with them."],"style":["patient","quick on their feet"],"skills":[{"label":"Damage","skills":[{"hero":"h5","id":"fire_arrow","name":"Fire Arrow","desc":"Pitch, a spark, and a hopeful arc.","tags":["fire"],"rank":2,"uses":15},{"hero":"h15","id":"bear_trap","name":"Bear Trap","desc":"Sprung, clamped, and very sorry for itself.","tags":["craft"],"rank":3,"uses":14},{"hero":"h15","id":"caltrops","name":"Caltrops","desc":"A handful of spikes, scattered where feet go.","tags":["craft","stealth"],"rank":3,"uses":13},{"hero":"h5","id":"aimed_shot","name":"Aimed Shot","desc":"Breathes out. Lets go.","tags":["crit","hunt"],"rank":1,"uses":13},{"hero":"h5","id":"called_shot","name":"Called Shot","desc":"Names the spot first. Then hits it.","tags":["crit"],"rank":1,"uses":8},{"hero":"h4","id":"feint","name":"Feint","desc":"Look over there.","tags":["stealth","crit"],"rank":1,"uses":7},{"hero":"h5","id":"game_shot","name":"Game Shot","desc":"Aims behind the shoulder, the way the old hunters taught.","tags":["hunt"],"rank":3,"uses":6},{"hero":"h4","id":"disarm","name":"Disarm","desc":"A twist of the wrist and their sword is on the floor.","tags":["crit"],"rank":1,"uses":2},{"hero":"h15","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":1,"uses":2}]},{"label":"Defence","skills":[{"hero":"h4","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":1,"uses":15},{"hero":"h4","id":"intercept","name":"Intercept","desc":"Steps in front of the blow meant for a friend.","tags":["guard"],"rank":1,"uses":7}]},{"label":"Tricks","skills":[{"hero":"h5","id":"hold_the_road","name":"Hold the Road","desc":"Nobody passes. Especially not you.","tags":["guard","travel"],"rank":1,"uses":12},{"hero":"h4","id":"wheel_about","name":"Wheel About","desc":"Turns the horse on a coin. Then picks the coin up.","tags":["ride"],"rank":2,"uses":2},{"hero":"h15","id":"nothing_twice","name":"Nothing Walks Twice","desc":"The fight starts with half of them already caught.","tags":["nature"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h4","id":"aura_of_courage","name":"Aura of Courage","desc":"Nobody runs while they stand.","tags":["holy","command"],"rank":1,"uses":0},{"hero":"h4","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":2,"uses":0},{"hero":"h4","id":"light_in_the_saddle","name":"Light in the Saddle","desc":"Moves like the horse is still under them.","tags":["ride"],"rank":1,"uses":0},{"hero":"h15","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":1,"uses":0},{"hero":"h15","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":1,"uses":0},{"hero":"h5","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h4","id":"horse_whisperer","name":"Horse Whisperer","desc":"Horses don't go lame on their watch, and thieves can't lead one off.","tags":["ride","beast"],"rank":1,"uses":0},{"hero":"h4","id":"eavesdropper","name":"Eavesdropper","desc":"Always sits near the important tables.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h4","id":"saddle_born","name":"Saddle-Born","desc":"Rides like they were born up there. Their horse goes a good deal further in a day.","tags":["ride"],"rank":2,"uses":0},{"hero":"h4","id":"whittler","name":"Whittling","desc":"Turns every stick into a small duck.","tags":[],"rank":1,"uses":0},{"hero":"h4","id":"angler","name":"Angler","desc":"Has a line in the water before the tent is up.","tags":[],"rank":1,"uses":0},{"hero":"h4","id":"lance_charge","name":"Lance Charge","desc":"From the saddle, the first blow of a fight lands like a falling wall.","tags":["ride"],"rank":1,"uses":0},{"hero":"h4","id":"trick_rider","name":"Trick Rider","desc":"Stands on the saddle at a gallop. Crowds pay for it.","tags":["ride"],"rank":1,"uses":0},{"hero":"h4","id":"saddle_hunt","name":"Saddle Hunt","desc":"Rides down supper from the saddle. One arrow, one rabbit.","tags":["crit","ride"],"rank":1,"uses":0},{"hero":"h15","id":"pathfinding","name":"Pathfinding","desc":"Knows the back ways.","tags":["travel","nature"],"rank":2,"uses":0},{"hero":"h15","id":"tailor","name":"Needle and Thread","desc":"Mends cloaks, patches tents, takes in trousers.","tags":["craft"],"rank":2,"uses":0},{"hero":"h15","id":"sermoniser","name":"Sermoniser","desc":"Has a sermon for every occasion, including this one.","tags":["holy"],"rank":1,"uses":0},{"hero":"h15","id":"bird_caller","name":"Bird Caller","desc":"Whistles. Something whistles back.","tags":["beast","nature"],"rank":1,"uses":0},{"hero":"h15","id":"animal_handler","name":"Animal Handler","desc":"Horses calm down. Dogs sit. Geese reconsider.","tags":["beast","nature"],"rank":1,"uses":0},{"hero":"h15","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":1,"uses":0},{"hero":"h5","id":"knot_tying","name":"Knotwork","desc":"Knows forty knots and when to use thirty-nine of them.","tags":["travel","craft"],"rank":1,"uses":0},{"hero":"h5","id":"spelunker","name":"Spelunker","desc":"Happiest in a crack the width of a loaf.","tags":["travel","stealth"],"rank":1,"uses":0},{"hero":"h5","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":2,"uses":0},{"hero":"h5","id":"cartography","name":"Cartography","desc":"Draws the map as they walk it.","tags":["travel"],"rank":2,"uses":0},{"hero":"h5","id":"trick_shot","name":"Trick Shot","desc":"Shoots the apple off your head. Asks first.","tags":["crit"],"rank":1,"uses":0},{"hero":"h5","id":"tracker","name":"Tracker","desc":"Reads a broken twig like a letter.","tags":["hunt","beast"],"rank":1,"uses":0},{"hero":"h5","id":"road_patrol","name":"Road Patrol","desc":"Walks the same ten miles every day, so the bandits do not get to.","tags":["guard","travel"],"rank":1,"uses":0}]}],"share":[{"hero":"h4","dmg":895,"healed":26,"taken":204,"kills":5,"row":"back"},{"hero":"h15","dmg":1209,"healed":0,"taken":28,"kills":5,"row":"back"},{"hero":"h5","dmg":2257,"healed":0,"taken":0,"kills":16,"row":"back"}],"ground":{"name":"Thornmere Ruins","fights":4}},"trophies":[{"boss":"Old Grizzlemaw","monster":"cave_bear","place":"The Wolf Den","day":6,"season":1,"fight":"f26"},{"boss":"The Silk Matriarch","monster":"spider_queen","place":"The Collapsed Mine","day":30,"season":1,"fight":"f74"}]};